<script setup lang="ts">
import{ref}from'vue';import UiIcon from'../components/UiIcon.vue';import{useApi,useEvents,useAction}from'../composables/api';import{route,yamVersion}from'../composables/state'
const confirm=window.confirm.bind(window),api=useApi(),installed=ref(false),transition=ref<any>({}),local=ref<any[]>([]),registries=ref<any[]>([]),results=ref<any[]>([]),searched=ref(false),registry=ref('official'),query=ref(''),name=ref(''),replace=ref(false),regName=ref(''),regUrl=ref(''),regKey=ref(''),path=ref(''),fileInput=ref<HTMLInputElement>(),state=ref('Получаем состояние YAM…'),{busy,message:report,run}=useAction(ref('Выбери действие.'))
const call=(path:string,body?:unknown,options={})=>api('/api/yam2/'+path,body,{timeout:300000,...options})
const action=(action:string,extra:Record<string,unknown>={})=>call('action',{action,registry:registry.value||'official',...extra})
async function refresh(){const v=await call('status');installed.value=v.installed;yamVersion.value=v.installed?'Установлен '+(v.version||'(версия не определена)'):'Ещё не установлен';state.value=v.installed?'Готов к установке и обновлению приложений.':'Установи актуальную ARM64-версию YAM. После установки заверши переход на новый менеджер.';transition.value=await call('retirement');if(!transition.value.pending&&transition.value.archive)state.value+=' Архив прежнего менеджера: '+transition.value.archive;if(!v.installed)return;const [p,r]=await Promise.allSettled([call('packages'),call('registries')]);if(p.status==='fulfilled')local.value=p.value;else report.value=p.reason.message;if(r.status==='fulfilled'){registries.value=r.value;if(!r.value.some((x:any)=>x.name===registry.value))registry.value=r.value[0]?.name||'official'}else report.value=r.reason.message}
function operate(fn:()=>Promise<any>){void run(async()=>{const v=await fn();if(v!==undefined)report.value=typeof v==='string'?v:v.report||JSON.stringify(v,null,2);await refresh()})}
function bootstrap(){if(confirm(installed.value?'Обновить YAM его штатным механизмом с проверкой подписи? Бинарник и база будут сохранены перед операцией.':'Установить актуальный YAM ARM64 в /data/yam? Скачивание около 4 МБ; старые yamd и .yap сохранятся.'))operate(()=>call('bootstrap',{}))}
function retire(){if(confirm('Остановить прежние приложения .yap, убрать yamd и его автозапуск? Весь каталог и загрузочный скрипт будут сохранены в архиве.'))operate(()=>call('retire',{}))}
function search(){operate(async()=>{const v=await action('search',{query:query.value});results.value=v.items;searched.value=true;return'Найдено: '+v.items.length})}
function pick(p:string){name.value=p;report.value='Пакет выбран. Проверь зависимости перед установкой.'}
function install(){if(confirm('Установить '+name.value.trim()+' и его зависимости? Проверь план установки.'))operate(()=>action('install',{name:name.value.trim(),allow_replacements:replace.value}))}
function remove(p:string){if(confirm('Удалить пакет '+p+'?'))operate(()=>action('remove',{name:p}))}
function removeRegistry(r:string){if(confirm('Удалить реестр '+r+'? Установленные пакеты сохранятся.'))operate(()=>action('registry-remove',{registry:r}))}
function upload(){const file=fileInput.value?.files?.[0];if(!file)return;if(!file.name.endsWith('.yampkg')||file.size>32*1048576){report.value='Нужен файл .yampkg до 32 МБ.';fileInput.value!.value='';return}if(!confirm('Установить локальный пакет '+file.name+'? Его код и postinstall получат права root.')){fileInput.value!.value='';return}operate(async()=>{try{return await call('upload',file,{raw:true,headers:replace.value?{'X-Yam-Allow-Replacements':'true'}:{}})}finally{fileInput.value!.value=''}})}
async function load(){if(busy.value)return;try{await refresh()}catch(e){state.value=(e as Error).message}}void load();useEvents(()=>{if(['yam','home'].includes(route.active))void load()})
</script>
<template><header class="page-head"><div><h1><UiIcon name="layers" :size="24"/>YAM v2</h1><div class="sub">Пакеты .yampkg · Мини 3 Про / pickle · управление на колонке</div></div><button class="btn" id="y2-refresh" :disabled="busy" @click="operate(async()=>{await refresh();return 'Данные обновлены.'})"><UiIcon name="refresh"/>Обновить данные</button></header>
<section class="card"><div class="card-head"><h2><UiIcon name="box"/>Менеджер пакетов</h2><span class="badge" id="y2-version">{{yamVersion}}</span></div><p class="hint" id="y2-state" role="status">{{state}}</p><div class="row"><button class="btn primary" id="y2-bootstrap" :disabled="busy" @click="bootstrap"><UiIcon name="dl"/>{{installed?'Обновить YAM':'Установить актуальный YAM'}}</button><button class="btn" id="y2-latest" :disabled="busy" @click="operate(async()=>{const v=await call('latest');return 'Последняя стабильная версия: '+v.version+'\n'+v.url})"><UiIcon name="search"/>Проверить версию</button><a class="btn" href="https://github.com/nyakokitsu/yam/releases" target="_blank" rel="noopener"><UiIcon name="arrow-right"/>Релизы ↗</a></div><details class="manager-details"><summary>Сведения о менеджере</summary><p class="hint">YAM v2 установлен в /data/yam и работает локально через CLI. Пакеты прежнего формата .yap не преобразуются в .yampkg.</p></details></section>
<section class="card" id="y2-transition" :hidden="!transition.pending"><h2><UiIcon name="info"/>Завершить переход</h2><p class="hint" id="y2-transition-note">Установи YAM v2, затем заверши переход: старые приложения .yap остановятся, yamd и его автозапуск будут отключены, каталог с данными переместится в архив. Файлы не удаляются.</p><button class="btn" id="y2-retire" :disabled="busy||!installed" @click="retire"><UiIcon name="archive"/>Завершить переход и убрать yamd</button></section>
<div id="y2-controls" :hidden="!installed"><section class="card"><div class="card-head"><h2><UiIcon name="box"/>Установленные пакеты <span class="badge" id="y2-count">{{local.length}}</span></h2><label class="btn upload-label"><UiIcon name="dl"/>Загрузить .yampkg<input type="file" id="y2-file" ref="fileInput" accept=".yampkg" hidden :disabled="busy" @change="upload"></label></div><p class="hint">Пакеты до 32 МБ. Устанавливай их из доверенных источников: они могут выполнять системные команды.</p><label class="toggle"><span>Разрешить замену конфликтов и зависимости Entware</span><input type="checkbox" id="y2-replace" v-model="replace" :disabled="busy"></label><div id="y2-packages" class="package-list"><article v-for="p in local" :key="p.name" class="card package-item"><div><h3><UiIcon name="box"/>{{p.name}}</h3><p>{{p.version}} · {{p.target}}</p></div><div class="row"><a v-if="p.homepage?.startsWith('https://')" class="btn sm" :href="p.homepage" target="_blank" rel="noopener noreferrer"><UiIcon name="arrow-right"/>Сайт пакета</a><button class="btn sm" :data-y2-files="p.name" :disabled="busy" @click="operate(()=>action('files',{name:p.name}))"><UiIcon name="folder"/>Файлы</button><button class="btn sm danger" :data-y2-remove="p.name" :disabled="busy" @click="remove(p.name)"><UiIcon name="trash"/>Удалить</button></div></article><p v-if="!local.length" class="hint">Пакетов .yampkg пока нет.</p></div></section>
<section class="card"><h2><UiIcon name="layers"/>Каталог и зависимости</h2><div class="catalog-search"><select class="field" id="y2-registry" v-model="registry" :disabled="busy" aria-label="Реестр"><option v-for="r in registries" :key="r.name" :value="r.name">{{r.name}}</option></select><input class="field" id="y2-query" v-model="query" :disabled="busy" type="search" placeholder="Название или описание" aria-label="Поиск YAM" @keydown.enter="search"><button class="btn" id="y2-search" :disabled="busy" @click="search"><UiIcon name="search"/>Найти</button></div><div id="y2-results" class="package-list"><article v-for="p in results" :key="p.name" class="card catalog-card"><div class="catalog-head"><span class="catalog-symbol" aria-hidden="true"><UiIcon name="box" :size="20"/></span><div class="catalog-title"><h3>{{p.name}}</h3><span class="badge">{{p.version}}</span></div></div><p class="catalog-summary">{{p.summary||'Описание отсутствует.'}}</p><div class="catalog-actions"><button class="btn sm" :data-y2-pick="p.name" :disabled="busy" @click="pick(p.name)"><UiIcon name="plus"/>Выбрать</button><button class="btn sm" :data-y2-info="p.name" :disabled="busy" @click="operate(()=>action('info',{name:p.name}))"><UiIcon name="info"/>Описание</button></div></article><p v-if="searched&&!results.length" class="hint">По этому запросу пакетов нет.</p></div><div class="catalog-install"><input class="field" id="y2-name" v-model="name" :disabled="busy" placeholder="namespace/name[@версия]" aria-label="Имя пакета"><button class="btn" id="y2-plan" :disabled="busy" @click="operate(()=>action('plan',{name:name.trim()}))"><UiIcon name="layers"/>Показать зависимости</button><button class="btn primary" id="y2-install" :disabled="busy" @click="install"><UiIcon name="dl"/>Установить</button></div><p class="hint">Каталог и индексы проверяются ключом Ed25519, скачанные пакеты — по размеру и SHA-256. Сначала проверь план установки: он не изменяет пакеты.</p></section>
<section class="card"><h2><UiIcon name="layers"/>Реестры</h2><div id="y2-registries"><div v-for="r in registries" :key="r.name" class="summary-row"><span><b>{{r.name}}</b> · {{r.url}}</span><button class="btn sm danger" :data-y2-reg-remove="r.name" :disabled="busy" @click="removeRegistry(r.name)"><UiIcon name="trash"/>Удалить</button></div><p v-if="!registries.length" class="hint">Реестр ещё не подключён. Добавь официальный реестр для поиска и установки по имени.</p></div><button class="btn" id="y2-official" :disabled="busy" @click="operate(()=>action('official-registry'))"><UiIcon name="plus"/>Подключить официальный реестр</button><details><summary>Добавить другой реестр</summary><div class="row"><input class="field" id="y2-reg-name" v-model="regName" :disabled="busy" placeholder="Имя"><input class="field" id="y2-reg-url" v-model="regUrl" :disabled="busy" type="url" placeholder="https://repo.example/v2"><input class="field" id="y2-reg-key" v-model="regKey" :disabled="busy" placeholder="ed25519:публичный-ключ-Base64"><button class="btn" id="y2-reg-add" :disabled="busy" @click="operate(()=>action('registry-add',{registry:regName.trim(),url:regUrl.trim(),key:regKey.trim()}))"><UiIcon name="plus"/>Добавить</button></div></details></section>
<section class="card"><h2><UiIcon name="shield"/>Диагностика и службы</h2><div class="row"><button class="btn" id="y2-doctor" :disabled="busy" @click="operate(()=>action('doctor'))"><UiIcon name="shield"/>Проверить пакеты (doctor)</button><button class="btn" id="y2-repair" :disabled="busy" @click="confirm('Восстановить ссылки пакетов по базе YAM?')&&operate(()=>action('repair'))"><UiIcon name="refresh"/>Восстановить ссылки (repair)</button><button class="btn" id="y2-entware" :disabled="busy" @click="operate(()=>action('entware'))"><UiIcon name="server"/>Проверить Entware</button><button class="btn" id="y2-services" :disabled="busy" @click="operate(()=>call('services'))"><UiIcon name="layers"/>Декларации служб</button></div><p class="hint">Службы запускает хост панели в разделе «Приложения». YAM управляет установкой пакетов; правила запуска и автозапуска сохраняются отдельно.</p><div class="row"><input class="field" id="y2-path" v-model="path" :disabled="busy" placeholder="bin/команда" aria-label="Относительный путь"><button class="btn" id="y2-which" :disabled="busy" @click="operate(()=>action('which',{path:path.trim()}))"><UiIcon name="search"/>Найти владельца файла</button></div></section></div>
<section class="card"><h2><UiIcon name="info"/>Результат операции</h2><pre class="out" id="y2-report" aria-live="polite">{{report}}</pre></section></template>
